const STORAGE_KEY = "image-sync-queue";

type QueueItem = {
  time: number;
  action: "delete";
};

type Queue = Record<string, QueueItem>;

const read = (): Queue => {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");
  } catch {
    return {};
  }
};

const write = (data: Queue) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

export const useImageSyncQueue = () => {
  const queueDelete = (id: string) => {
    const data = read();

    data[id] = {
      time: Date.now(),
      action: "delete",
    };

    write(data);
  };

  const clear = (id: string) => {
    const data = read();
    delete data[id];
    write(data);
  };

  const check = (rows: any[]) => {
    const data = read();

    const filteredRows = rows.filter((row) => !data[row.id]);

    return { filteredRows };
  };

  return { queueDelete, clear, check };
};